pub const bun = @import("bun");
pub const tagged_union = @import("./tagged_union.zig");
pub const ListContainerType = enum {
    array_list,
    baby_list,
    small_list,
    pub fn get(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
    pub fn has(__cp_s: []const u8) bool { return std.meta.stringToEnum(@This(), __cp_s) != null; }
    pub fn fromName(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
    pub fn name(__cp_self: @This()) []const u8 { return @tagName(__cp_self); }
};

pub const ListContainerInfo = struct {
    list: ListContainerType,
    child: type,
};

pub const TaggedUnion = tagged_union.TaggedUnion;
const empty_decls: [0]std.builtin.Type.Declaration = undefined;

pub fn OptionalChild(comptime T: type) type {
        const tyinfo = @typeInfo(T);
        if ((tyinfo != .pointer)) {
            _ = @compileError("OptionalChild(T) requires that T be a pointer to an optional type.");
        }
        const child = @typeInfo(tyinfo.pointer.child);
        if ((child != .Optional)) {
            _ = @compileError("OptionalChild(T) requires that T be a pointer to an optional type.");
        }
        return child.Optional.child;
}

pub fn EnumFields(comptime T: type) []const std.builtin.Type.EnumField {
        const tyinfo = @typeInfo(T);
        return (switch (tyinfo) {
.@"union" => std.meta.fields(tyinfo.@"union".tag_type.?),
.@"enum" => tyinfo.@"enum".fields,
else => @compileError("Used `EnumFields(T)` on a type that is not an `enum` or a `union(enum)`"),
});
}

pub fn ReturnOfMaybe(comptime function: anytype) type {
        const Func = @TypeOf(function);
        const typeinfo: std.builtin.Type.Fn = (switch (@typeInfo(Func)) {
.@"fn" => |f| f,
.pointer => |ptr| @typeInfo(ptr.child).@"fn",
else => @compileError(("Expected a function type, got " ++ @typeName(Func))),
});
        const MaybeType = ((typeinfo.return_type) orelse (@compileError("Expected the function to have a return type")));
        return MaybeResult(MaybeType);
}

pub fn MaybeResult(comptime MaybeType: type) type {
        const maybe_ty_info = @typeInfo(MaybeType);
        const maybe = maybe_ty_info.@"union";
        if ((maybe.fields.len != 2)) {
            _ = @compileError("Expected the Maybe type to be a union(enum) with two variants");
        }
        if ((!std.mem.eql(u8, (if (@typeInfo(@TypeOf(maybe.fields[0])) == .@"enum" or @typeInfo(@TypeOf(maybe.fields[0])) == .@"union") @tagName(maybe.fields[0]) else maybe.fields[0].name), "err"))) {
            _ = @compileError(std.fmt.comptimePrint("Expected the first field of the Maybe type to be \"err\", got: {s}", .{ (if (@typeInfo(@TypeOf(maybe.fields[0])) == .@"enum" or @typeInfo(@TypeOf(maybe.fields[0])) == .@"union") @tagName(maybe.fields[0]) else maybe.fields[0].name) }));
        }
        if ((!std.mem.eql(u8, (if (@typeInfo(@TypeOf(maybe.fields[1])) == .@"enum" or @typeInfo(@TypeOf(maybe.fields[1])) == .@"union") @tagName(maybe.fields[1]) else maybe.fields[1].name), "result"))) {
            _ = @compileError(std.fmt.comptimePrint("Expected the second field of the Maybe type to be \"result\"{s}", .{ (if (@typeInfo(@TypeOf(maybe.fields[1])) == .@"enum" or @typeInfo(@TypeOf(maybe.fields[1])) == .@"union") @tagName(maybe.fields[1]) else maybe.fields[1].name) }));
        }
        return maybe.fields[1].type;
}

pub fn ReturnOf(comptime function: anytype) type {
        return ReturnOfType(@TypeOf(function));
}

pub fn ReturnOfType(comptime Type: type) type {
        const typeinfo: std.builtin.Type.Fn = (switch (@typeInfo(Type)) {
.@"fn" => |f| f,
.pointer => |ptr| @typeInfo(ptr.child).@"fn",
else => @compileError(("Expected a function type, got " ++ @typeName(Type))),
});
        return ((typeinfo.return_type) orelse (void));
}

pub fn typeName(comptime Type: type) []const u8 {
        const name = @typeName(Type);
        return typeBaseName(name);
}

pub inline fn typeBaseName(comptime fullname: [:0]const u8) [:0]const u8 {
        _ = @setEvalBranchQuota(1000000);
        const baseidx = (comptime std.mem.indexOf(u8, fullname, "("));
        if ((baseidx != null)) {
            return (comptime fullname);
        }
        const idx = (comptime std.mem.lastIndexOf(u8, fullname, "."));
        const name = (if ((idx == null)) fullname else fullname[(idx.? + 1)..]);
        return (comptime name);
}

pub fn enumFieldNames(comptime Type: type) []const []const u8 {
        const src_names = (blk: {
        break :blk (std.meta.fieldNames(Type)).*;

});
        var names = src_names;
        _ = &names;
        var i: usize = 0;
        _ = &i;
        for (cp_iter_slice(src_names)) |name| {
            _ = &name;
            if (bun.strings.eqlAnyComptime(name, (&.{ "_none", "", "_" }))) {
                continue;
            }
            names[cp_cast_int(usize, i)] = name;
            i = (i + 1);
        }
        return names[0..i];
}

pub fn banFieldType(comptime Container: type, comptime T: type) void {
        comptime {
        for (cp_iter_slice(std.meta.fields(Container))) |field| {
            _ = &field;
            if ((field.type == T)) {
                _ = @compileError(std.fmt.comptimePrint("{s} field \"{s}\" not allowed in {s}", .{ typeName(T), (if (@typeInfo(@TypeOf(field)) == .@"enum" or @typeInfo(@TypeOf(field)) == .@"union") @tagName(field) else field.name), typeName(Container) }));
            }
        }

}
}

pub fn Item(comptime T: type) type {
        switch (@typeInfo(T)) {
.pointer => |ptr| {
if ((ptr.size == .one)) {
            switch (@typeInfo(ptr.child)) {
.array => |array| {
return array.child;
},
else => {

},
}
        }
        return ptr.child;
},
else => {
return std.meta.Child(T);
},
}
}

pub fn ConcatArgs1(comptime func: anytype, a: anytype, args_: anytype) std.meta.ArgsTuple(@TypeOf(func)) {
        var args: std.meta.ArgsTuple(@TypeOf(func)) = undefined;
        _ = &args;
        @field(args, "0") = a;
        inline for (0..args_.len) |i| {
            @field(args, std.fmt.comptimePrint("{d}", .{ (i + 1) })) = args_[@as(usize, @intCast(i))];
        }
        return args;
}

pub inline fn ConcatArgs2(comptime func: anytype, a: anytype, b: anytype, args_: anytype) std.meta.ArgsTuple(@TypeOf(func)) {
        var args: std.meta.ArgsTuple(@TypeOf(func)) = undefined;
        _ = &args;
        @field(args, "0") = a;
        @field(args, "1") = b;
        inline for (0..args_.len) |i| {
            @field(args, std.fmt.comptimePrint("{d}", .{ (i + 2) })) = args_[@as(usize, @intCast(i))];
        }
        return args;
}

pub inline fn ConcatArgs4(comptime func: anytype, a: anytype, b: anytype, c: anytype, d: anytype, args_: anytype) std.meta.ArgsTuple(@TypeOf(func)) {
        var args: std.meta.ArgsTuple(@TypeOf(func)) = undefined;
        _ = &args;
        @field(args, "0") = a;
        @field(args, "1") = b;
        @field(args, "2") = c;
        @field(args, "3") = d;
        inline for (0..args_.len) |i| {
            @field(args, std.fmt.comptimePrint("{d}", .{ (i + 4) })) = args_[@as(usize, @intCast(i))];
        }
        return args;
}

pub fn CreateUniqueTuple(comptime N: comptime_int, comptime types: [N]type) type {
        var tuple_fields: [N]std.builtin.Type.StructField = undefined;
        _ = &tuple_fields;
        inline for (0..types.len) |i| {
            const T = types[@as(usize, @intCast(i))];
            _ = @setEvalBranchQuota(10000);
            var num_buf: [128]u8 = undefined;
            _ = &num_buf;
            tuple_fields[cp_cast_int(usize, i)] = std.builtin.Type.StructField{ .name = ((std.fmt.bufPrintZ((&num_buf), "{d}", .{ @as(usize, @intCast(i)) })) catch unreachable), .type = T, .default_value_ptr = null, .is_comptime = false, .alignment = (if ((@sizeOf(T) > 0)) @alignOf(T) else 0) };
        }
        return @Type(std.builtin.Type{ .@"struct" = std.builtin.Type.Struct{ .is_tuple = true, .layout = .auto, .decls = empty_decls[0..], .fields = tuple_fields[0..] } });
}

pub fn hasStableMemoryLayout(comptime T: type) bool {
        const tyinfo = @typeInfo(T);
        return (switch (tyinfo) {
.Type => true,
.Void => true,
.Bool => true,
.Int => true,
.Float => true,
.@"enum" => {
{
            if (tyinfo.@"enum".is_exhaustive) {
                return false;
            }
            return hasStableMemoryLayout(tyinfo.@"enum".tag_type);
        }
},
.@"struct" => (switch (tyinfo.@"struct".layout) {
.auto => {
{
            inline for (tyinfo.@"struct".fields) |field| {
                if ((!hasStableMemoryLayout(field.field_type))) {
                    return false;
                }
            }
            return true;
        }
},
.@"extern" => true,
.@"packed" => false,
}),
.@"union" => (switch (tyinfo.@"union".layout) {
.auto => {
{
            if (((tyinfo.@"union".tag_type == null) or (!hasStableMemoryLayout(tyinfo.@"union".tag_type.?)))) {
                return false;
            }
            inline for (tyinfo.@"union".fields) |field| {
                if ((!hasStableMemoryLayout(field.type))) {
                    return false;
                }
            }
            return true;
        }
},
.@"extern" => true,
.@"packed" => false,
}),
else => true,
});
}

pub fn isSimpleCopyType(comptime T: type) bool {
        _ = @setEvalBranchQuota(1000000);
        const tyinfo = @typeInfo(T);
        return (switch (tyinfo) {
.void => true,
.bool => true,
.int => true,
.float => true,
.@"enum" => true,
.@"struct" => {
{
            inline for (tyinfo.@"struct".fields) |field| {
                if ((!isSimpleCopyType(field.type))) {
                    return false;
                }
            }
            return true;
        }
},
.@"union" => {
{
            inline for (tyinfo.@"union".fields) |field| {
                if ((!isSimpleCopyType(field.type))) {
                    return false;
                }
            }
            return true;
        }
},
.optional => isSimpleCopyType(tyinfo.optional.child),
else => false,
});
}

pub fn isScalar(comptime T: type) bool {
        return (if ((T == i32) or (T == u32) or (T == i64) or (T == u64) or (T == f32) or (T == f64) or (T == bool)) true else {
{
            const tyinfo = @typeInfo(T);
            if ((tyinfo == .@"enum")) {
                return true;
            }
            return false;
        }
});
}

pub fn isSimpleEqlType(comptime T: type) bool {
        const tyinfo = @typeInfo(T);
        return (switch (tyinfo) {
.type => true,
.void => true,
.bool => true,
.int => true,
.float => true,
.@"enum" => true,
.@"struct" => |struct_info| (struct_info.layout == .@"packed"),
else => false,
});
}

pub fn looksLikeListContainerType(comptime T: type) ?ListContainerInfo {
        const tyinfo = @typeInfo(T);
        if ((tyinfo == .@"struct")) {
            const fields = tyinfo.@"struct".fields;
            if ((((fields.len == 2) and std.mem.eql(u8, (if (@typeInfo(@TypeOf(fields[0])) == .@"enum" or @typeInfo(@TypeOf(fields[0])) == .@"union") @tagName(fields[0]) else fields[0].name), "items")) and std.mem.eql(u8, (if (@typeInfo(@TypeOf(fields[1])) == .@"enum" or @typeInfo(@TypeOf(fields[1])) == .@"union") @tagName(fields[1]) else fields[1].name), "capacity"))) {
                return ListContainerInfo{ .list = .array_list, .child = std.meta.Child(fields[0].type) };
            }
            if (@hasDecl(T, "looksLikeContainerTypeBabyList")) {
                return ListContainerInfo{ .list = .baby_list, .child = T.looksLikeContainerTypeBabyList };
            }
            if (@hasDecl(T, "looksLikeContainerTypeSmallList")) {
                return ListContainerInfo{ .list = .small_list, .child = T.looksLikeContainerTypeSmallList };
            }
        }
        return null;
}

pub fn Tagged(comptime U: type, comptime T: type) type {
        var info: std.builtin.Type.Union = @typeInfo(U).@"union";
        _ = &info;
        info.tag_type = T;
        info.decls = empty_decls[0..];
        info.layout = .auto;
        return @Type(std.builtin.Type{ .@"union" = info });
}

pub fn SliceChild(comptime T: type) type {
        const tyinfo = @typeInfo(T);
        if (((tyinfo == .pointer) and (tyinfo.pointer.size == .slice))) {
            return tyinfo.pointer.child;
        }
        return T;
}

pub fn useAllFields(comptime T: type, unused: VoidFields(T)) void {
        _ = &unused;
}

pub fn VoidFields(comptime T: type) type {
        const fields = @typeInfo(T).@"struct".fields;
        var new_fields = (blk: {
        break :blk (fields[0..fields.len]).*;

});
        _ = &new_fields;
        for (cp_mut_slice(&new_fields)) |*field| {
            _ = &field;
            (field.*).type = void;
            (field.*).default_value_ptr = null;
        }
        return @Type(std.builtin.Type{ .@"struct" = std.builtin.Type.Struct{ .layout = .auto, .fields = new_fields[0..], .decls = empty_decls[0..], .is_tuple = false } });
}

pub fn voidFieldTypeDiscardHelper(data: anytype) void {
        _ = &data;
}

pub fn hasDecl(comptime T: type, comptime name: []const u8) bool {
        return (switch (@typeInfo(T)) {
.@"struct", .@"union", .@"enum", .@"opaque" => @hasDecl(T, name),
else => false,
});
}

pub fn hasField(comptime T: type, comptime name: []const u8) bool {
        return (switch (@typeInfo(T)) {
.@"struct", .@"union", .@"enum" => @hasField(T, name),
else => false,
});
}
